function paintMap(gc,w,h,large){let base=imgs.parchment;if(base.complete&&base.naturalWidth)gc.drawImage(base,0,0,w,h);else{gc.fillStyle='#dec496';gc.fillRect(0,0,w,h);}const px=x=>x/WORLD_W*w,py=y=>y/WORLD_H*h;gc.save();gc.lineCap='round';gc.strokeStyle='#7b9c99';gc.lineWidth=large?20:7;gc.beginPath();for(let i=0;i<=WORLD_W;i+=15){let x=px(i),y=py(riverY(i));i===0?gc.moveTo(x,y):gc.lineTo(x,y);}gc.stroke();gc.strokeStyle='#e5cf98';gc.lineWidth=large?8:3;gc.beginPath();gc.moveTo(px(0),py(1590));gc.quadraticCurveTo(px(820),py(1230),px(1480),py(960));gc.quadraticCurveTo(px(2000),py(940),px(2300),py(490));gc.stroke();
// Mountains sketched as triangular ink contours
for(let i=0;i<125;i++){let xx=1300+hash(i,18,S?.seed||0)*1500,yy=hash(i,14,S?.seed||0)*1930,x=px(xx),y=py(yy),ss=large?9:3.1;gc.strokeStyle='#806844b8';gc.lineWidth=large?1.4:.6;gc.beginPath();gc.moveTo(x-ss,y+ss*.65);gc.lineTo(x,y-ss);gc.lineTo(x+ss,y+ss*.65);gc.stroke();}
if(S){gc.fillStyle='#684b32';for(let c of S.caves){if(!c.visited)continue;let x=px(c.x),y=py(c.y);gc.beginPath();gc.arc(x,y,large?7:2.6,0,7);gc.fill();}if(S.clues.length>=4){let c=S.caves[S.special],x=px(c.x),y=py(c.y);gc.strokeStyle='#b23a22';gc.lineWidth=large?4:2;gc.beginPath();gc.arc(x,y,large?35:10,0,7);gc.stroke();gc.fillStyle='#bd4c27';gc.font=`bold ${large?27:9}px serif`;gc.fillText('★',x-10,y-10);}
gc.fillStyle='#6f4429';gc.beginPath();gc.arc(px(TOWN.x),py(TOWN.y),large?13:5,0,7);gc.fill();gc.fillStyle='#e9d69d';gc.fillRect(px(TOWN.x)-(large?6:2),py(TOWN.y)-(large?6:2),large?12:4,large?12:4);gc.fillStyle='#bd302b';gc.beginPath();gc.moveTo(px(S.x),py(S.y)-(large?13:6));gc.lineTo(px(S.x)-(large?8:4),py(S.y)+(large?7:4));gc.lineTo(px(S.x)+(large?8:4),py(S.y)+(large?7:4));gc.closePath();gc.fill();if(large){gc.fillStyle='#77522c';gc.font='bold 24px serif';gc.fillText('GOLDFIELD',px(TOWN.x)-30,py(TOWN.y)+40);gc.font='italic 22px serif';gc.fillText('Superstition Mountains',px(1680),py(190));}}
gc.restore();}
function renderMap(){mc.clearRect(0,0,mini.width,mini.height);paintMap(mc,mini.width,mini.height,false);}
function draw(){ctx.clearRect(0,0,W,H);if(!S||scene==='title')drawTitle();else if(scene==='town')drawTown();else if(scene==='world')drawWorld();else if(scene==='river')drawRiver();else if(scene==='cave')drawCave();else if(scene==='combat')drawCombat();else if(scene==='treasure')drawTreasure();else if(scene==='camp')drawCamp();else if(scene==='interior')drawInterior();else if(scene==='ending')drawEnding();if(S&&scene!=='title')drawParticles(.016);}
function update(dt){t+=dt;if(!S||S.gameOver||S.victory)return;dust(dt);if(miniGame)miniGame.phase+=dt*miniGame.speed;if(scene==='combat'){combatTick(dt);return;}if(!EL('modal').hidden)return;
const k=(...names)=>names.some(n=>keys.has(n)||moves.has(n)),left=k('arrowleft','a','left'),right=k('arrowright','d','right'),up=k('arrowup','w','up'),down=k('arrowdown','s','down');let vx=Number(right)-Number(left),vy=Number(down)-Number(up);if(vx&&vy){vx*=.7071;vy*=.7071;}
if(scene==='town'&&(vx||vy)){S.townX=cap(S.townX+vx*dt*237,65,1215);S.walkFacing=vx<0?-1:vx>0?1:S.walkFacing;advance(dt*1.9);}
if(scene==='world'){if(target&&(vx||vy))target=null;if(target&&!vx&&!vy){let dx=target.x-S.x,dy=target.y-S.y,dist=Math.hypot(dx,dy);if(dist<17)target=null;else {vx=dx/dist;vy=dy/dist;}}if(vx||vy){let slow=onRiver(S.x,S.y)?.72:1,sp=(S.energy<20?92:185)*slow,dx=vx*dt*sp,dy=vy*dt*sp,oldX=S.x,oldY=S.y;S.x=cap(S.x+dx,40,WORLD_W-40);S.y=cap(S.y+dy,40,WORLD_H-40);if(vx)S.walkFacing=vx<0?-1:1;let len=d2(oldX,oldY,S.x,S.y);S.walkDist+=len;advance(len/15.5);if(S.walkDist>250&&!onRiver(S.x,S.y)&&!nearTown()&&Math.random()<dt*.033){S.walkDist=-400;spawnDanger();}}
}
if(scene==='cave'&&(vx||vy)){S.caveX=cap(S.caveX+vx*dt*180,83,1130);if(vx)S.walkFacing=vx<0?-1:1;advance(dt*1.7);}
if(scene==='cave'&&S.flags.poison&&Math.random()<dt*.07)S.health=cap(S.health-1,0,100);
}
function loop(time){let dt=cap(((time-last)||16)/1000,.001,.07);last=time;frameN++;update(dt);draw();if(frameN%12===0){renderMap();if(S)updateHUD();}requestAnimationFrame(loop);}
function stageCoord(e){let r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H};}
canvas.addEventListener('pointermove',e=>{mouseStage=stageCoord(e);pointer.active=true;});
canvas.addEventListener('pointerleave',()=>{pointer.active=false;});
canvas.addEventListener('click',e=>{if(!S)return;let p=stageCoord(e);canvas.focus();if(scene==='town'){let hit=FACS.find(f=>Math.abs(p.x-f.x)<85&&p.y>258&&p.y<455);if(hit){openFacility(hit.id);return;}S.townX=cap(p.x,65,1215);}
else if(scene==='world'){let zoom=1.1,wx=S.x-W/(2*zoom)+p.x/zoom,wy=S.y-H/(2*zoom)+p.y/zoom;target={x:cap(wx,35,WORLD_W-35),y:cap(wy,35,WORLD_H-35)};}
else if(scene==='combat')shoot();else if(miniGame)strike();else if(scene==='cave'){S.caveX=cap(p.x,80,1130);}
});
window.addEventListener('keydown',e=>{let key=e.key.toLowerCase();let block=['arrowup','arrowdown','arrowleft','arrowright',' ','space','f6'];if(block.includes(key))e.preventDefault();if(!EL('modal').hidden){if(key==='escape'){closeModal();if(scene==='interior')exitFacility();}return;}keys.add(key);if(!S)return;if(e.repeat&&(key==='e'||key===' '))return;if(key==='escape'){if(scene==='interior')exitFacility();else if(scene==='river'||scene==='camp')goWorld();else if(scene==='cave')leaveCave();}if(key==='e')interact();if(key===' '){if(miniGame)strike();else if(scene==='combat')shoot();else interact();}if(key==='m')showMap();if(key==='i')showInventory();if(key==='j')journal();if(key==='f6'){save();notice('모험이 저장되었습니다.');}if(['1','2','3','4'].includes(key)){let buttons=[...EL('actionBtns').children];buttons[Number(key)-1]?.click();}});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();moves.clear();});
EL('startBtn').onclick=newGame;EL('continueBtn').onclick=()=>{if(!load())notice('저장된 모험이 없습니다.');};EL('helpBtn').onclick=help;EL('saveBtn').onclick=()=>{if(S){save();notice('모험을 저장했습니다.');}else notice('새 모험을 먼저 시작하세요.');};EL('mapExpandBtn').onclick=showMap;mini.onclick=showMap;EL('cluesBtn').onclick=showClues;EL('restBtn').onclick=()=>{if(!S)return;if(scene==='world')camp();else if(scene==='town')openFacility('saloon');else notice('야영은 황야에서만 가능합니다.');};EL('fullBtn').onclick=()=>{if(!document.fullscreenElement)EL('app').requestFullscreen?.().catch(()=>notice('전체 화면을 사용할 수 없습니다.'));else document.exitFullscreen?.();};EL('soundBtn').onclick=()=>{soundOn=!soundOn;EL('soundBtn').textContent=soundOn?'♫ 소리 끄기':'♪ 소리 켜기';tone(730,.17,'triangle');};
for(let bt of document.querySelectorAll('[data-panel]'))bt.onclick=()=>{if(!S)return;if(bt.dataset.panel==='inventory')showInventory();if(bt.dataset.panel==='map')showMap();if(bt.dataset.panel==='journal')journal();};
function actionTouch(){if(miniGame)strike();else if(scene==='combat')shoot();else interact();}
EL('touchAction').addEventListener('click',actionTouch);document.querySelectorAll('[data-move]').forEach(b=>{let d=b.dataset.move;b.addEventListener('pointerdown',e=>{e.preventDefault();moves.add(d);b.setPointerCapture(e.pointerId)});const off=()=>moves.delete(d);b.addEventListener('pointerup',off);b.addEventListener('pointercancel',off);b.addEventListener('lostpointercapture',off);});
if(window.matchMedia?.('(pointer:coarse)').matches||window.innerWidth<650)document.body.classList.add('mobile');
try{EL('continueBtn').hidden=!localStorage.getItem(SAVE);}catch(e){}
